'use strict';
/* A reviewed external bank statement. Reconciliation never posts a money entry. */
window.BankReconciliation = (() => {
  let dialog, model=null, dirty=false, busy=false, sequence=0, opener=null;
  const arr=value=>Array.isArray(value)?value:[], q=selector=>dialog.querySelector(selector);
  const amount=value=>`<bdi class="br-money">${money(Number(value||0))}</bdi>`;
  const textAmount=value=>(Number(value||0)/100).toFixed(2);
  const label=value=>({draft:'مسودة مطابقة',confirmed:'مطابقة معتمدة',cancelled:'مسودة ملغاة',voided:'اعتماد مبطل'})[value]||value;
  const effective=d=>d.effective_status||(d.void?'voided':d.status)||'draft';
  const button=(title,action,attrs='',primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" data-reconciliation-action="${action}" ${attrs}>${esc(title)}</button>`;
  const note=(message,tone='')=>`<p class="br-note ${tone}">${esc(message)}</p>`;
  const field=(name,title,value='',type='text',required=false,wide=false)=>`<label class="${wide?'br-wide':''}">${esc(title)}${required?' *':''}<input data-reconciliation-field="${name}" type="${type}" value="${esc(value??'')}" ${required?'required':''} maxlength="${name==='reference'?100:200}" ${type==='number'?'step="0.01" inputmode="decimal"':''}></label>`;
  const memo=(name,title,value='')=>`<label class="br-wide">${esc(title)}<textarea data-reconciliation-field="${name}" rows="2" maxlength="2000">${esc(value||'')}</textarea></label>`;
  const kpi=(title,value,tone='')=>`<article class="br-kpi ${tone}"><small>${esc(title)}</small><strong>${amount(value)}</strong><span>EGP</span></article>`;
  const empty=message=>`<div class="br-empty">${illustration('bank')}<span>${esc(message)}</span></div>`;
  const sourceLabels={opening_balance:'رصيد افتتاحي',bank_receipt:'متحصل بنكي',bank_payment:'مدفوع بنكي',bank_fee:'عمولة بنكية',bank_transfer:'تحويل بنك وخزينة',bank_reversal:'عكس مستند بنك',supplier_payment:'سداد مورد',supplier_payment_reversal:'عكس سداد مورد',supplier_cheque_clearance:'صرف شيك مورد',supplier_cheque_bounce:'شيك مرتد',opening_cheque_clearance:'صرف شيك افتتاحي',supplier_refund:'استرداد مورد',supplier_refund_reversal:'عكس استرداد مورد',withholding_remittance:'توريد خصم ضريبي',withholding_remittance_reversal:'عكس توريد خصم ضريبي'};
  function cents(value,zero=true){const raw=String(value??'').trim();if(!/^-?\d+(\.\d{1,2})?$/.test(raw))throw Error('أدخل المبلغ بالجنيه بدقة منزلتين عشريتين. الإيداع موجب والسحب سالب.');const negative=raw.startsWith('-'),[whole,fraction='']=raw.replace(/^-/,'').split('.'),n=Number(whole)*100+Number(fraction.padEnd(2,'0'));if(!Number.isSafeInteger(n)||n>10000000000000||(!zero&&n===0))throw Error('المبلغ خارج النطاق المسموح');return negative?-n:n;}
  function ensure(){
    if(dialog)return;
    dialog=document.createElement('dialog');dialog.id='bank-reconciliation-window';dialog.dir='rtl';dialog.setAttribute('aria-labelledby','bank-reconciliation-title');
    dialog.innerHTML='<header class="br-header"><span class="br-art"></span><div><small>BANK STATEMENT RECONCILIATION</small><h2 id="bank-reconciliation-title"></h2><p id="bank-reconciliation-subtitle"></p></div><button type="button" class="br-close" data-reconciliation-action="close" aria-label="إغلاق التسوية البنكية">×</button></header><div class="br-scroll"><p id="bank-reconciliation-error" class="error" role="alert"></p><div id="bank-reconciliation-body"></div></div><footer class="br-footer" id="bank-reconciliation-footer"></footer>';
    document.body.appendChild(dialog);q('.br-art').innerHTML=illustration('bank');
    dialog.addEventListener('cancel',event=>{event.preventDefault();close();});
    dialog.addEventListener('click',event=>{const control=event.target.closest('[data-reconciliation-action]');if(control&&!control.disabled)dispatch(control).catch(error);});
    dialog.addEventListener('input',input);
    dialog.addEventListener('change',event=>{if(event.target.id==='reconciliation-csv-file')readFile(event.target.files?.[0]).catch(error);});
    window.addEventListener('beforeunload',event=>{if(dirty){event.preventDefault();event.returnValue='';}});
  }
  function error(err){ensure();q('#bank-reconciliation-error').textContent=err.message||String(err);if(!dialog.open)toast(err.message||String(err));}
  function title(name,subtitle=''){q('#bank-reconciliation-title').textContent=name;q('#bank-reconciliation-subtitle').textContent=subtitle;q('#bank-reconciliation-error').textContent='';}
  function show(){ensure();if(!dialog.open){opener=document.activeElement;dialog.showModal();}}
  function display(html,footer=''){q('#bank-reconciliation-body').innerHTML=html;q('#bank-reconciliation-footer').innerHTML=footer||button('إغلاق','close');lock();}
  function discard(){return !busy&&(!dirty||confirm('توجد تعديلات لم تحفظ في التسوية البنكية. هل تريد تركها؟'));}
  function close(){if(!discard())return;++sequence;model=null;dirty=false;dialog?.close();if(opener?.isConnected)opener.focus();}
  function lock(){if(!dialog)return;dialog.querySelectorAll('button,input,textarea').forEach(element=>{if(!busy&&element.dataset.brBusy==='true'){element.disabled=false;delete element.dataset.brBusy;}else if(busy&&!element.disabled){element.disabled=true;element.dataset.brBusy='true';}});printGuard();}
  async function load(loader){if(!discard())return;dirty=false;const current=++sequence;model=null;show();title('التسوية البنكية','قراءة كشوف البنك والحركات المحفوظة…');display('<div class="br-loading" role="status">جاري تجهيز المطابقة…</div>');try{const next=await loader();if(current!==sequence||!dialog.open)return;model=next;render();}catch(err){if(current===sequence&&dialog.open)error(err);}}
  async function mutate(task){if(busy)return;busy=true;lock();try{return await task();}finally{busy=false;lock();}}
  function editable(){return model?.view==='document'&&model.data.status==='draft';}
  function changed(){dirty=true;if(model){model.lastPreview=model.preview||model.lastPreview;model.preview=null;}const p=q('#reconciliation-pending');if(p)p.hidden=false;printGuard();}
  function printGuard(){if(!dialog)return;dialog.querySelectorAll('[data-reconciliation-action="print"]').forEach(element=>element.disabled=busy||dirty);}
  function statementIds(group){if(group.statement_line_ids)return arr(group.statement_line_ids).map(Number);const keys=arr(group.statement_line_keys);return keys.map(key=>model.data.lines.findIndex(line=>String(line.line_key)===String(key))+1).filter(id=>id>0);}
  const bookIds=group=>arr(group.book_line_ids||group.ledger_line_ids).map(Number);
  function normalized(document){const d={...document,opening_balance:document.opening_balance??textAmount(document.opening_balance_cents),closing_balance:document.closing_balance??textAmount(document.closing_balance_cents),lines:arr(document.lines).map(line=>{const n=line.amount_cents??cents(line.amount);return {...line,line_key:String(line.line_key||crypto.randomUUID()),direction:n<0?'withdrawal':'deposit',amount:textAmount(Math.abs(n))};}),matches:arr(document.matches||document.groups).map(group=>({...group})),opening_outstanding_line_ids:arr(document.opening_outstanding_line_ids||document.prior_ledger_line_ids).map(Number)};return d;}
  function emptyDocument(preset={}){const day=today();return{request_key:crypto.randomUUID(),status:'draft',account_id:null,from_date:day.slice(0,7)+'-01',to_date:day,reference:'',opening_balance:'',closing_balance:'',prepared_by:'',reviewed_by:'',notes:'',lines:[],matches:[],opening_outstanding_line_ids:[],...preset};}
  async function open(){return load(async()=>({view:'list',documents:arr(await api('bank-reconciliations')),config:await api('bank-reconciliation-config'),search:''}));}
  async function newDocument(preset={}){if(typeof preset==='number')preset={account_id:preset};return load(async()=>{const config=await api('bank-reconciliation-config');const documents=arr(await api('bank-reconciliations'));const accountId=preset.account_id||null,existing=accountId?documents.find(d=>d.status==='draft'&&Number(d.account_id)===Number(accountId)):null;if(existing){const data=await api('bank-reconciliations/'+existing.id);return documentModel(config,data);}const data=emptyDocument(preset);if(!data.account_id&&arr(config.bank_accounts||config.accounts).length===1)data.account_id=Number((config.bank_accounts||config.accounts)[0].id);applyLatestDefaults(config,data);return{view:'document',config,data,preview:null,lastPreview:null,selectedStatements:new Set(),selectedBooks:new Set(),csv:null};});}
  function applyLatestDefaults(config,data){if(!data.account_id)return;let previous=arr(config.latest_by_account).find(d=>Number(d.account_id)===Number(data.account_id));if(!previous&&config.latest_by_account&&typeof config.latest_by_account==='object')previous=config.latest_by_account[data.account_id];if(previous?.to_date){const date=new Date(previous.to_date+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+1);data.from_date=date.toISOString().slice(0,10);if(data.to_date<data.from_date)data.to_date=data.from_date;data.opening_balance=textAmount(previous.closing_balance_cents??previous.statement_closing_cents??0);}}
  function documentModel(config,data){return{view:'document',config,data:normalized(data),preview:data.status==='draft'?data.preview||null:data.snapshot||null,lastPreview:data.preview||data.snapshot||null,selectedStatements:new Set(),selectedBooks:new Set(),csv:null};}
  async function openDocument(id){return load(async()=>{const [config,data]=await Promise.all([api('bank-reconciliation-config'),api('bank-reconciliations/'+Number(id))]);return documentModel(config,data);});}
  function render(){if(model.view==='list')return renderList();if(model.view==='document')return renderDocument();if(model.view==='void')return renderVoid();if(model.view==='journal')return renderJournal();if(model.view==='bank-line')return renderBankLineChoice();}
  function account(){return arr(model.config?.bank_accounts||model.config?.accounts).find(a=>Number(a.id||a.account_id)===Number(model.data.account_id));}
  function accountName(a){return a?(a.code||a.account_code||'')+' • '+(a.name||a.account_name||''):'اختيار حساب البنك';}
  function frozenAccountName(){const d=model.data;return d.account_code||d.account_name?(d.account_code||'')+' • '+(d.account_name||''):accountName(account());}
  function renderList(){title('التسوية البنكية','كشف البنك الخارجي مقابل حركات الأستاذ • دون تكرار قيود');display(`<section class="br-hero">${illustration('bank')}<div><h3>كل حركة لها مصدرها</h3><p>أدخل كشف البنك أو استورده، ثم اربط بنوده بالقيود المعتمدة وراجع البنود التي لم تظهر بعد.</p></div>${button('تسوية بنكية جديدة','new','',true)}</section><section class="br-section"><div class="br-section-head"><h3>كشوف ومطابقات البنك</h3><input type="search" data-reconciliation-field="search" aria-label="بحث في التسويات البنكية" placeholder="الكود أو حساب البنك أو المرجع…" value="${esc(model.search)}"></div><div id="reconciliation-list"></div></section>${arr(model.config.notes).map(n=>note(typeof n==='string'?n:n.message||'')).join('')}`,button('تسوية جديدة','new','',true)+button('تحديث','list')+'<span class="br-spacer"></span>'+button('إغلاق','close'));renderListRows();}
  function renderListRows(){const term=model.search.toLocaleLowerCase().trim(),documents=model.documents.filter(d=>!term||[d.code,d.reference,d.account_code,d.account_name,d.from_date,d.to_date].some(v=>String(v||'').toLocaleLowerCase().includes(term)));q('#reconciliation-list').innerHTML=documents.length?`<div class="br-table-wrap"><table class="br-table"><thead><tr><th>المستند / المرجع</th><th>البنك</th><th>فترة الكشف</th><th>رصيد كشف البنك</th><th>الحالة</th><th></th></tr></thead><tbody>${documents.map(d=>`<tr><td><bdi>${esc(d.code)}</bdi><small>${esc(d.reference)}</small></td><td>${esc(d.account_code||'')}<small>${esc(d.account_name||'')}</small></td><td><bdi>${esc(d.from_date)} — ${esc(d.to_date)}</bdi></td><td>${amount(d.closing_balance_cents??d.statement_closing_cents??d.totals?.statement_closing_cents)}</td><td><span class="br-status ${esc(effective(d))}">${esc(label(effective(d)))}</span></td><td>${button('فتح','open',`data-id="${d.id}"`)}</td></tr>`).join('')}</tbody></table></div>`:empty('لا توجد تسويات بنكية محفوظة تطابق العرض.');}
  function payload(){const d=model.data;if(!d.account_id)throw Error('اختر حساب البنك');if(!d.from_date||!d.to_date||!d.reference?.trim())throw Error('أكمل فترة الكشف ومرجعه');if(d.from_date>d.to_date)throw Error('بداية الكشف لا تتجاوز نهايته');return{request_key:d.request_key,...(d.id?{reconciliation_id:d.id,revision:d.revision}:{}),account_id:Number(d.account_id),from_date:d.from_date,to_date:d.to_date,reference:d.reference,opening_balance:String(d.opening_balance),closing_balance:String(d.closing_balance),prepared_by:d.prepared_by||'',reviewed_by:d.reviewed_by||'',notes:d.notes||'',lines:d.lines.map((line,index)=>{const signed=cents(line.amount,false)*(line.direction==='withdrawal'?-1:1);if(cents(line.amount,false)<0)throw Error('استخدم قيمة موجبة في مبلغ البند وحدد إيداعًا أو سحبًا');const result={line_key:line.line_key||String(index+1),date:line.date,value_date:line.value_date||line.date,reference:line.reference||'',description:line.description||'',amount_cents:signed};if(line.balance_cents!==undefined&&line.balance_cents!==null)result.balance_cents=line.balance_cents;return result;}),matches:arr(d.matches).map(group=>({statement_line_ids:statementIds(group),book_line_ids:bookIds(group),note:group.note||''})),opening_outstanding_line_ids:arr(d.opening_outstanding_line_ids).map(Number)};}
  function localTotals(){const d=model.data;let opening=0,closing=0,net=0,valid=true;try{opening=cents(d.opening_balance);closing=cents(d.closing_balance);}catch(_){valid=false;}for(const line of d.lines){try{net+=Math.abs(cents(line.amount))*(line.direction==='withdrawal'?-1:1);}catch(_){valid=false;}}return{opening,closing,net,difference:opening+net-closing,valid};}
  function renderDocument(){const d=model.data,editing=editable(),p=model.preview||(!editing?d.snapshot:null),a=account();title('التسوية البنكية',(d.code||'رقم المستند عند الحفظ')+' • '+label(effective(d)));let html=note('المطابقة تربط كشف البنك بالقيود المسجلة فقط، ولا تنشئ مصروفًا أو إيداعًا أو قيد سداد جديدًا. الحركات البنكية الناقصة تسجل أولًا من مستندها الأصلي.');if(d.void)html+=note('أُبطل الاعتماد بتاريخ '+d.void.business_date+' • '+d.void.reference+' • '+d.void.reason,'warning');if(d.book_changed)html+=note('تغيرت القيود المرتبطة بالموقف بعد التقاطه. الأرقام المعتمدة أدناه محفوظة؛ راجع القراءة الحالية قبل الاعتماد على شهادة سابقة.','warning');html+=`<section class="br-section"><div class="br-section-head"><h3>بيانات كشف البنك</h3><span class="br-status ${esc(effective(d))}">${esc(label(effective(d)))}</span></div>${editing?`<div class="br-grid"><div class="br-choice"><span>حساب البنك *</span>${button(accountName(a),'pick-account')}</div>${field('reference','مرجع كشف البنك',d.reference,'text',true)}${field('from_date','من تاريخ',d.from_date,'date',true)}${field('to_date','حتى تاريخ',d.to_date,'date',true)}${field('opening_balance','رصيد بداية الكشف EGP',d.opening_balance,'number',true)}${field('closing_balance','رصيد نهاية الكشف EGP',d.closing_balance,'number',true)}${field('prepared_by','أعد المطابقة',d.prepared_by,'text',true)}${field('reviewed_by','راجع المطابقة',d.reviewed_by,'text',true)}${memo('notes','ملاحظات المراجعة',d.notes)}</div>`:readDetails([['البنك',frozenAccountName()],['الفترة',d.from_date+' — '+d.to_date],['مرجع الكشف',d.reference],['أعدّه',d.prepared_by],['راجعه',d.reviewed_by],['ملاحظات',d.notes]])}${note('الأرقام من وجهة نظر الفندق: الإيداع يزيد رصيد البنك، والسحب يخفضه. أدخل الرصيد السالب بعلامة ناقص عند وجود سحب على المكشوف.')}</section>`;html+=statementSection(editing);if(editing&&model.csv)html+=csvSection();html+=`<p id="reconciliation-pending" class="br-note warning" ${dirty?'':'hidden'}>توجد تغييرات؛ حدّث المعاينة واحفظ المسودة قبل الاعتماد أو الطباعة.</p>`;if(p)html+=previewSection(p,editing);else html+=note('بعد إدخال بيانات الكشف وبنوده، استخدم «تحديث المعاينة» لإحضار القيود واختيار المطابقات.');const footer=(editing?button('تحديث المعاينة','preview')+button('حفظ المسودة','save','',true)+(d.id?button('اعتماد المطابقة','confirm','',true)+button('إلغاء المسودة','cancel'):''):'')+(d.id?button('طباعة المطابقة','print'):'')+(d.status==='confirmed'&&!d.void?button('إبطال الاعتماد','void'):'')+'<span class="br-spacer"></span>'+button('قائمة التسويات','list')+button('إغلاق','close');display(html,footer);computed();selection();}
  function readDetails(pairs){return`<dl class="br-details">${pairs.filter(pair=>pair[1]!==undefined&&pair[1]!==null&&pair[1]!=='').map(([key,value])=>`<dt>${esc(key)}</dt><dd>${esc(value)}</dd>`).join('')}</dl>`;}
  function statementSection(editing){const d=model.data;return`<section class="br-section"><div class="br-section-head"><div><h3>بنود كشف البنك الخارجي</h3><p class="br-muted">البيان والمرجع من كشف البنك، والمبلغ بالقيمة الفعلية.</p></div>${editing?`<div class="br-tools">${button('إضافة بند','add-line')}${button('استيراد CSV','load-csv')}<input type="file" id="reconciliation-csv-file" accept=".csv,.txt,text/csv,text/plain" hidden></div>`:''}</div><div class="br-table-wrap"><table class="br-table br-statement-table"><thead><tr><th>#</th><th>التاريخ</th><th>تاريخ القيمة</th><th>المرجع</th><th>البيان</th><th>الحركة</th><th>المبلغ EGP</th>${editing?'<th></th>':''}</tr></thead><tbody>${d.lines.map((line,index)=>editing?`<tr><td>${index+1}</td>${lineInput(line,index,'date','date')}${lineInput(line,index,'value_date','date')}${lineInput(line,index,'reference')}${lineInput(line,index,'description')}<td>${button(line.direction==='withdrawal'?'سحب −':'إيداع +','line-direction',`data-index="${index}" data-direction="${line.direction==='withdrawal'?'deposit':'withdrawal'}"`)}</td>${lineInput(line,index,'amount','number')}<td>${button('حذف','remove-line',`data-index="${index}"`)}</td></tr>`:`<tr><td>${index+1}</td><td>${esc(line.date)}</td><td>${esc(line.value_date||line.date)}</td><td>${esc(line.reference)}</td><td>${esc(line.description)}</td><td>${line.direction==='withdrawal'?'سحب':'إيداع'}</td><td>${amount(Math.abs(Number(line.amount_cents??cents(line.amount))))}</td></tr>`).join('')||`<tr><td colspan="${editing?8:7}">${empty('لا توجد بنود في الكشف. يمكن اعتماد كشف بلا حركة إذا تطابقت أرصدته.')}</td></tr>`}</tbody></table></div><div class="br-local-totals" data-reconciliation-local-totals></div></section>`;}
  function lineInput(line,index,name,type='text'){return`<td><input type="${type}" data-reconciliation-line-field="${name}" data-index="${index}" value="${esc(line[name]??'')}" aria-label="${esc({date:'تاريخ البند',value_date:'تاريخ القيمة',reference:'مرجع البند',description:'بيان البنك',amount:'المبلغ'}[name])} ${index+1}" ${type==='number'?'min="0.01" step="0.01" inputmode="decimal"':''} maxlength="${name==='description'?500:150}"></td>`;}
  function computed(){const element=q('[data-reconciliation-local-totals]');if(!element)return;const t=localTotals();element.innerHTML=`<span>بداية الكشف <b>${amount(t.opening)}</b></span><span>صافي البنود <b>${amount(t.net)}</b></span><span>نهاية الكشف <b>${amount(t.closing)}</b></span><span class="${t.valid&&t.difference===0?'br-good':'br-bad'}">فرق جمع الكشف <b>${amount(t.difference)}</b></span>`;}
  function input(event){const element=event.target;if(!model||busy)return;const name=element.dataset.reconciliationField;if(name==='search'&&model.view==='list'){model.search=element.value;renderListRows();return;}if(name&&model.view==='void'){model.data[name]=element.value;dirty=true;return;}if(!editable())return;if(name?.startsWith('csv.')){if(model.csv){model.csv[name.slice(4)]=element.value;model.csv.inspection=null;}return;}if(name==='match_note'){model.matchNote=element.value;return;}if(name){model.data[name]=element.value;changed();computed();return;}const lineName=element.dataset.reconciliationLineField;if(lineName){const index=Number(element.dataset.index),line=model.data.lines[index];if(!line)return;line[lineName]=element.value;if(lineName==='amount')clearLineMatches(index+1);changed();computed();}}
  function clearLineMatches(id){const matches=model.data.matches.filter(group=>!statementIds(group).includes(id));if(matches.length!==model.data.matches.length){model.data.matches=matches;toast('تغير مبلغ البند؛ أُلغيت مطابقته السابقة حتى تراجع المبلغ الجديد.');}}
  function bookLines(preview){return arr(preview.book_lines||preview.ledger_candidates);}
  function bookId(line){return Number(line.line_id||line.id);}
  function signed(line){return Number(line.amount_cents??Number(line.debit_cents||0)-Number(line.credit_cents||0));}
  function usedStatements(){return new Set(model.data.matches.flatMap(statementIds));}
  function usedBooks(){return new Set(model.data.matches.flatMap(bookIds));}
  function previewSection(p,editing){const t=p.totals||{},matched=arr(p.matches||p.groups),unmatchedStatement=arr(p.unmatched_statement_lines),unmatchedBook=arr(p.unmatched_book_lines);return`<section class="br-section"><div class="br-section-head"><h3>موقف المطابقة</h3><span class="br-status ${p.can_confirm?'confirmed':'draft'}">${!editing?(model.data.void?'شهادة محفوظة • اعتماد مبطل':'مطابقة معتمدة محفوظة'):p.can_confirm?'جاهزة للاعتماد':'تحتاج استكمالًا'}</span></div><div class="br-kpis">${kpi('نهاية كشف البنك',t.statement_closing_cents)}${kpi('الرصيد الدفتري',t.book_closing_cents)}${kpi('حركات دفترية لم تظهر',t.unmatched_book_cents)}${kpi('رصيد البنك بعد البنود القائمة',t.adjusted_statement_cents)}${kpi('فرق المطابقة',t.difference_cents,Number(t.difference_cents)?'br-danger':'br-success')}</div>${arr(p.blockers).map(issue=>note(issue.message||String(issue),'warning')).join('')}${p.previous?note('التسوية السابقة '+p.previous.code+' • حتى '+p.previous.to_date+'؛ البنود الدفترية القائمة تُنقل تلقائيًا دون إعادة اختيارها.'):priorSection(p,editing)}${editing?matchingSection(p):''}<div class="br-section-head"><h3>مجموعات المطابقة المحفوظة (${matched.length})</h3>${editing&&model.data.matches.length?button('إلغاء كل المطابقات','clear-matches'):''}</div>${groupsTable(matched,editing)}<div class="br-two"><section><h3>بنود كشف لم تطابق (${unmatchedStatement.length})</h3>${unmatchedStatement.length?statementReadTable(unmatchedStatement,true):note('كل بنود كشف البنك مرتبطة بحركات دفترية.','success')}</section><section><h3>حركات دفترية قائمة (${unmatchedBook.length})</h3>${unmatchedBook.length?bookTable(unmatchedBook,false,true):note('لا توجد حركات دفترية معلقة.','success')}</section></div>${note('الحركة الدفترية القائمة لم يظهر مقابلها في كشف البنك بعد؛ تبقى ظاهرة وتُنقل للتسوية التالية. الشيك الصادر غير المصروف على حساب الالتزام لا يُخصم من البنك مرة أخرى.')}${pendingCheques(p.pending_cheques)}</section>`;}
  function priorSection(p,editing){const selected=new Set(arr(model.data.opening_outstanding_line_ids).map(Number)),candidates=arr(p.available_prior_lines),t=p.totals||{};return`<section class="br-bridge"><h3>مراجعة بداية أول كشف</h3>${note('رصيد الدفاتر قبل الكشف '+money(t.book_opening_cents||0)+' • البنود السابقة المختارة '+money(t.opening_outstanding_cents||0)+' • بداية كشف البنك '+money(t.statement_opening_cents||0)+' • فرق البداية '+money(t.opening_difference_cents||0))}${candidates.length?`<details><summary>حركات دفترية أقدم لم تظهر قبل بداية أول كشف</summary>${note('اختر فقط الحركات السابقة التي كانت فعلًا قائمة عند بداية كشف البنك. لا تختار قيد الرصيد الافتتاحي.')}${bookTable(candidates,editing,false,'prior',selected)}</details>`:''}</section>`;}
  function matchingSection(p){const suggestions=arr(p.suggestions),st=usedStatements(),bk=usedBooks(),availableStatements=model.data.lines.map((line,index)=>({...line,id:index+1,line_no:index+1,amount_cents:Math.abs(cents(line.amount||'0'))*(line.direction==='withdrawal'?-1:1)})).filter(line=>!st.has(line.id)),availableBooks=bookLines(p).filter(line=>!bk.has(bookId(line)));return`<section class="br-matching"><div class="br-section-head"><h3>اختيار بنود المطابقة</h3>${button('إلغاء الاختيار','clear-selection')}</div>${suggestions.length?`<div class="br-suggestions"><h4>اقتراحات للمراجعة (${suggestions.length})</h4>${suggestions.slice(0,30).map((suggestion,index)=>`<div><span>كشف ${statementIds(suggestion).join('، ')} ↔ ${bookIds(suggestion).length} حركة دفترية • ${amount(suggestion.amount_cents)}<small>${esc(suggestion.note||'قيمة متساوية؛ راجع التاريخ والمرجع قبل قبول الاقتراح.')}</small></span>${button('مراجعة الاختيار','suggestion',`data-index="${index}"`)}</div>`).join('')}${note('الاقتراح يحدد البنود للمراجعة فقط؛ إنشاء المطابقة يحتاج الضغط على «مطابقة المختار».')}</div>`:''}<div class="br-two"><section><h4>كشف البنك • إيداع موجب / سحب سالب</h4>${statementSelectTable(availableStatements)}</section><section><h4>حركات الأستاذ على حساب البنك</h4>${bookTable(availableBooks,true)}</section></div><div class="br-selection" id="reconciliation-selection"></div><div class="br-match-tools">${field('match_note','ملاحظة المطابقة الاختيارية',model.matchNote||'')}${button('مطابقة المختار','match-selected','',true)}</div></section>`;}
  function statementSelectTable(lines){return`<div class="br-table-wrap"><table class="br-table br-match-table"><thead><tr><th>اختيار</th><th>البند / التاريخ</th><th>البيان / المرجع</th><th>المبلغ</th></tr></thead><tbody>${lines.map(line=>`<tr class="${model.selectedStatements.has(line.id)?'br-selected':''}"><td>${button(model.selectedStatements.has(line.id)?'محدد ✓':'اختيار','toggle-statement',`data-id="${line.id}"`)}</td><td>${line.id}<small>${esc(line.date)}</small></td><td>${esc(line.description)}<small>${esc(line.reference)}</small></td><td>${amount(line.amount_cents)}</td></tr>`).join('')||'<tr><td colspan="4">كل بنود كشف البنك موزعة على المطابقات.</td></tr>'}</tbody></table></div>`;}
  function bookTable(lines,selecting=false,drill=false,kind='book',selected=null){selected=selected||model.selectedBooks;return`<div class="br-table-wrap"><table class="br-table br-match-table"><thead><tr>${selecting?'<th>اختيار</th>':''}<th>التاريخ / المستند</th><th>البيان / المرجع</th><th>المبلغ</th>${drill?'<th></th>':''}</tr></thead><tbody>${lines.map(line=>{const id=bookId(line);return`<tr class="${selecting&&selected.has(id)?'br-selected':''}">${selecting?`<td>${button(selected.has(id)?'محدد ✓':'اختيار',kind==='prior'?'toggle-prior':'toggle-book',`data-id="${id}"`)}</td>`:''}<td>${esc(line.entry_date||line.date)}<small><bdi>${esc(line.document_code||line.journal_code||'')}</bdi></small></td><td>${esc(line.source_label||sourceLabels[line.source_type]||'حركة حساب')}<small>${esc(line.reference||'')}</small><small>${esc(line.party_name||line.supplier_name||'')}</small></td><td>${amount(signed(line))}</td>${drill?`<td>${line.journal_id?button('القيد','journal',`data-id="${line.journal_id}"`):''}${line.action?button('المصدر','source',`data-line-id="${id}"`):''}</td>`:''}</tr>`;}).join('')||`<tr><td colspan="${3+Number(selecting)+Number(drill)}">لا توجد حركات دفترية في هذا العرض.</td></tr>`}</tbody></table></div>`;}
  function statementReadTable(lines,actions=false){return`<div class="br-table-wrap"><table class="br-table br-match-table"><thead><tr><th>البند / التاريخ</th><th>المرجع / البيان</th><th>المبلغ</th>${actions?'<th></th>':''}</tr></thead><tbody>${lines.map(line=>`<tr><td>${line.id||line.line_no}<small>${esc(line.date)}</small></td><td>${esc(line.reference||'')}<small>${esc(line.description||'')}</small></td><td>${amount(line.amount_cents)}</td>${actions?`<td>${button('مراجعة مصدر الحركة','record-bank-line',`data-id="${line.id||line.line_no}"`)}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
  function groupsTable(groups,editing=false){const p=model.preview||model.lastPreview||{},allBooks=bookLines(p);return`<div class="br-table-wrap"><table class="br-table"><thead><tr><th>المجموعة</th><th>بنود كشف البنك</th><th>حركات الدفاتر</th><th>المبلغ</th><th>الملاحظة</th>${editing?'<th></th>':''}</tr></thead><tbody>${groups.map((group,index)=>`<tr><td>${index+1}</td><td>${statementIds(group).join('، ')}</td><td>${bookIds(group).map(id=>{const line=allBooks.find(l=>bookId(l)===id);return esc(line?.document_code||line?.journal_code||id);}).join('، ')}</td><td>${amount(group.amount_cents??statementIds(group).reduce((sum,id)=>{const line=model.data.lines[id-1];return sum+(line?Math.abs(cents(line.amount))*(line.direction==='withdrawal'?-1:1):0);},0))}</td><td>${esc(group.note||'—')}</td>${editing?`<td>${button('إلغاء المطابقة','remove-match',`data-index="${index}"`)}</td>`:''}</tr>`).join('')||`<tr><td colspan="${editing?6:5}">لا توجد مجموعات مطابقة محفوظة.</td></tr>`}</tbody></table></div>`;}
  function pendingCheques(cheques,printing=false){const lines=arr(cheques);if(!lines.length)return'';return`<${printing?'section':'details'} class="br-pending-cheques"><${printing?'h3':'summary'}>شيكات صادرة لم يثبت صرفها (${lines.length}) • معلومات مستقلة</${printing?'h3':'summary'}>${note('هذه التزامات شيكات قائمة، وليست خصمًا جديدًا من رصيد البنك. عند الصرف تسجل الحركة من مستند الشيك ثم تطابق مع كشف البنك.')}<div class="br-table-wrap"><table class="br-table"><thead><tr><th>الشيك</th><th>المستفيد / الاستحقاق</th><th>صافي القيمة</th></tr></thead><tbody>${lines.map(line=>`<tr><td>${esc(line.cheque_number||line.details?.cheque_number||line.code||'')}</td><td>${esc(line.beneficiary||line.details?.beneficiary||line.supplier_name||'')}<small>${esc(line.due_date||line.details?.due_date||'')}</small></td><td>${amount(line.amount_cents??line.net_cash_cents)}</td></tr>`).join('')}</tbody></table></div></${printing?'section':'details'}>`;}
  function selectionTotals(){const p=model.preview||model.lastPreview||{};let statement=0,book=0;for(const id of model.selectedStatements){const line=model.data.lines[id-1];if(line)statement+=Math.abs(cents(line.amount||'0'))*(line.direction==='withdrawal'?-1:1);}for(const id of model.selectedBooks){const line=bookLines(p).find(l=>bookId(l)===id);if(line)book+=signed(line);}return{statement,book,difference:statement-book};}
  function selection(){const element=q('#reconciliation-selection');if(!element)return;const t=selectionTotals();element.innerHTML=`<span>مختار من الكشف ${model.selectedStatements.size} • ${amount(t.statement)}</span><span>مختار من الدفاتر ${model.selectedBooks.size} • ${amount(t.book)}</span><b class="${t.difference?'br-bad':'br-good'}">فرق الاختيار ${amount(t.difference)}</b>`;}
  async function preview(){const input=payload(),p=await api('bank-reconciliation-preview','POST',input);model.preview=p;model.lastPreview=p;model.selectedStatements=new Set();model.selectedBooks=new Set();renderDocument();selection();return p;}
  async function save(){const data=payload(),d=await api('bank-reconciliations'+(model.data.id?'/'+model.data.id:''),model.data.id?'PUT':'POST',data);model=documentModel(model.config,d);dirty=false;renderDocument();selection();await refresh();toast('تم حفظ مسودة التسوية البنكية • '+d.code);}
  async function confirmDocument(){if(dirty)throw Error('احفظ تعديلات المسودة قبل اعتماد المطابقة');const d=await api('bank-reconciliations/'+model.data.id+'/confirm','POST',{revision:model.data.revision});model=documentModel(model.config,d);dirty=false;renderDocument();await refresh();toast('تم اعتماد المطابقة وحفظ شهادة التسوية البنكية');}
  async function cancelDocument(){if(!confirm('إلغاء المسودة وإبقاؤها في السجل؟'))return;const d=await api('bank-reconciliations/'+model.data.id,'PUT',{revision:model.data.revision,action:'cancel'});model=documentModel(model.config,d);dirty=false;renderDocument();await refresh();}
  function pickAccount(){const accounts=arr(model.config.bank_accounts||model.config.accounts);picker('اختيار حساب البنك',accounts.map(a=>({id:Number(a.id||a.account_id),label:accountName(a),detail:a.bank_name||''})),selected=>{if(!editable())return;if(model.data.account_id&&Number(model.data.account_id)!==Number(selected.id)&&model.data.matches.length&&!confirm('تغيير البنك يلغي المطابقات واختيار البنود السابقة. متابعة؟'))return;model.data.account_id=Number(selected.id);model.data.matches=[];model.data.opening_outstanding_line_ids=[];applyLatestDefaults(model.config,model.data);changed();renderDocument();});}
  function addLine(){model.data.lines.push({line_key:crypto.randomUUID(),date:model.data.to_date||today(),value_date:'',reference:'',description:'',direction:'deposit',amount:''});changed();renderDocument();q(`[data-reconciliation-line-field="date"][data-index="${model.data.lines.length-1}"]`)?.focus();}
  function removeLine(index){if(model.data.matches.length&&!confirm('حذف بند يعيد ترقيم الكشف ويلغي المطابقات الحالية. متابعة؟'))return;model.data.lines.splice(index,1);model.data.matches=[];changed();renderDocument();}
  function toggle(set,id){if(set.has(id))set.delete(id);else set.add(id);}
  function toggleSelection(kind,id){toggle(kind==='statement'?model.selectedStatements:model.selectedBooks,id);renderDocument();selection();}
  async function togglePrior(id){const selected=new Set(model.data.opening_outstanding_line_ids);toggle(selected,id);model.data.opening_outstanding_line_ids=[...selected];changed();await preview();}
  async function matchSelected(){if(!model.preview)throw Error('حدّث المعاينة أولًا بعد تعديل البيانات');if(!model.selectedStatements.size||!model.selectedBooks.size)throw Error('اختر بندًا واحدًا على الأقل من كشف البنك وحركات الدفاتر');const selectedAmounts=[...model.selectedStatements].map(id=>{const l=model.data.lines[id-1];return Math.abs(cents(l.amount))*(l.direction==='withdrawal'?-1:1);}).concat([...model.selectedBooks].map(id=>signed(bookLines(model.preview).find(l=>bookId(l)===id))));if(!selectedAmounts.every(n=>n>0)&&!selectedAmounts.every(n=>n<0))throw Error('كل مجموعة تطابق تحتاج حركات بالاتجاه نفسه؛ افصل الإيداعات عن السحوبات.');if(selectionTotals().difference!==0)throw Error('إجمالي المختار من كشف البنك يجب أن يساوي إجمالي المختار من الدفاتر');model.data.matches.push({statement_line_ids:[...model.selectedStatements].sort((a,b)=>a-b),book_line_ids:[...model.selectedBooks].sort((a,b)=>a-b),note:model.matchNote||''});model.selectedStatements.clear();model.selectedBooks.clear();model.matchNote='';changed();await preview();}
  function suggest(index){const group=arr(model.preview?.suggestions)[index];if(!group)return;model.selectedStatements=new Set(statementIds(group));model.selectedBooks=new Set(bookIds(group));renderDocument();selection();q('#reconciliation-selection')?.scrollIntoView({block:'nearest'});}
  async function removeMatch(index){model.data.matches.splice(index,1);changed();await preview();}
  async function csvStart(){model.csv={csv_text:'',encoding:'utf-8',delimiter:'auto',date_format:'YYYY-MM-DD',decimal_separator:'point',amount_mode:'columns',columns:{},inspection:null,file:null,fileName:''};renderDocument();q('#reconciliation-csv-file').click();}
  async function readFile(file){if(!file||!editable())return;if(file.size>2*1024*1024)throw Error('حجم ملف CSV بحد أقصى ٢ ميجابايت');if(!model.csv)model.csv={encoding:'utf-8',delimiter:'auto',date_format:'YYYY-MM-DD',decimal_separator:'point',amount_mode:'columns',columns:{}};const current=model,context=model.csv,seq=sequence,bytes=await file.arrayBuffer();if(model!==current||model.csv!==context||seq!==sequence||!dialog.open)return;context.bytes=bytes;context.fileName=file.name;decodeCsv();await inspectCsv();}
  function decodeCsv(){const csv=model.csv;if(!csv?.bytes)return;let encoding=csv.encoding||'utf-8';const bytes=new Uint8Array(csv.bytes);if(encoding==='utf-8'&&bytes[0]===255&&bytes[1]===254)encoding='utf-16le';if(encoding==='utf-8'&&bytes[0]===254&&bytes[1]===255)encoding='utf-16be';try{csv.csv_text=new TextDecoder(encoding,{fatal:true}).decode(csv.bytes);}catch(_){throw Error('تعذر قراءة الملف بهذا الترميز. اختر Windows-1256 للملف العربي القديم أو احفظ CSV بترميز UTF-8.');}}
  function csvPayload(){const csv=model.csv;return{csv_text:csv.csv_text,delimiter:csv.delimiter,date_format:csv.date_format,decimal_separator:csv.decimal_separator,amount_mode:csv.amount_mode,columns:{...csv.columns}};}
  async function inspectCsv(){decodeCsv();const current=model,context=model.csv,seq=sequence,result=await api('bank-statement-inspect','POST',csvPayload());if(model!==current||model.csv!==context||seq!==sequence||!dialog.open)return;context.inspection=result;if(!context.amountModeExplicit&&result.proposed_amount_mode)context.amount_mode=result.proposed_amount_mode;if(!Object.keys(context.columns).length)context.columns={...(result.proposed_mapping||{})};renderDocument();}
  async function parseCsv(){if(model.data.lines.length&&!confirm('استبدال بنود الكشف الحالية بالملف وإلغاء المطابقات الحالية؟'))return;const result=await api('bank-statement-import','POST',csvPayload());model.data.lines=arr(result.lines).map(line=>({...line,line_key:crypto.randomUUID(),direction:line.amount_cents<0?'withdrawal':'deposit',amount:textAmount(Math.abs(line.amount_cents))}));model.data.matches=[];model.data.opening_outstanding_line_ids=[];model.csv=null;changed();renderDocument();toast('تمت قراءة '+result.count+' بندًا من ملف البنك؛ راجع الرصيد والتواريخ قبل الحفظ.');}
  const csvColumnNames={date:'تاريخ الحركة',value_date:'تاريخ القيمة • اختياري',description:'البيان • اختياري',reference:'المرجع • اختياري',deposit:'الإيداع / دائن كشف البنك',withdrawal:'السحب / مدين كشف البنك',amount:'المبلغ الموقّع',balance:'الرصيد بعد الحركة • اختياري'};
  function csvChoice(name,title,options){const csv=model.csv;return`<div class="br-choice"><span>${esc(title)}</span><div class="br-options">${options.map(([id,text])=>button(text,'csv-option',`data-name="${name}" data-value="${id}" aria-pressed="${String(csv[name]===id)}"`)).join('')}</div></div>`;}
  function csvSection(){const csv=model.csv,inspection=csv.inspection,headers=arr(inspection?.headers);return`<section class="br-section br-csv"><div class="br-section-head"><h3>معاينة استيراد كشف البنك CSV</h3>${button('إغلاق الاستيراد','close-csv')}</div>${note('الملف يقرأ على جهازك داخل التطبيق؛ المعاينة لا تحفظ مستندًا أو تنشئ قيدًا. الإيداع موجب والسحب سالب من وجهة نظر الفندق.')}${csv.fileName?note('الملف: '+csv.fileName):note('اختر ملف CSV لإظهار عناوين الأعمدة وربطها.')}${csvChoice('encoding','ترميز النص',[['utf-8','UTF-8'],['windows-1256','Windows-1256']])}<div class="br-grid">${csvChoice('delimiter','فاصل الأعمدة',[['auto','تلقائي'],['comma','فاصلة ,'],['semicolon','فاصلة منقوطة ;'],['tab','Tab']])}${csvChoice('date_format','صيغة التاريخ',[['YYYY-MM-DD','2026-10-30'],['DD/MM/YYYY','30/10/2026'],['DD-MM-YYYY','30-10-2026'],['MM/DD/YYYY','10/30/2026']])}${csvChoice('decimal_separator','الفاصل العشري',[['point','نقطة 1,234.50'],['comma','فاصلة 1.234,50']])}${csvChoice('amount_mode','شكل قيمة الحركة',[['columns','عمود إيداع وعمود سحب'],['signed','عمود مبلغ موجب أو سالب']])}</div><div class="br-tools">${button('اختيار ملف CSV','choose-csv-file')}${button('فحص الأعمدة','inspect-csv')}</div>${inspection?`<div class="br-grid br-column-map">${Object.entries(csvColumnNames).filter(([name])=>csv.amount_mode==='signed'?!['deposit','withdrawal'].includes(name):name!=='amount').map(([name,title])=>{const selected=headers.find(h=>Number(h.index)===Number(csv.columns[name])&&csv.columns[name]!==null&&csv.columns[name]!==undefined);return`<div class="br-choice"><span>${esc(title)}</span>${button(selected?selected.index+1+' • '+selected.name:'اختيار العمود','pick-csv-column',`data-column="${name}"`)}</div>`;}).join('')}</div><p class="br-muted">عدد البنود ${Number(inspection.row_count||0)} • العينة أول ${arr(inspection.sample_rows).length} صفوف</p><div class="br-table-wrap"><table class="br-table"><thead><tr>${headers.map(h=>`<th>${Number(h.index)+1} • ${esc(h.name)}</th>`).join('')}</tr></thead><tbody>${arr(inspection.sample_rows).map(row=>`<tr>${arr(row).map(value=>`<td>${esc(value)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${arr(inspection.notes).map(message=>note(message)).join('')}<div class="br-tools">${button('قراءة البنود وإضافتها للكشف','parse-csv','',true)}</div>`:''}</section>`;}
  function pickCsvColumn(name){const headers=arr(model.csv?.inspection?.headers);picker('اختيار عمود '+csvColumnNames[name],[{id:-1,label:'عدم استخدام عمود لهذا الحقل',detail:'للبيانات الاختيارية فقط'},...headers.map(header=>({id:Number(header.index),label:header.index+1+' • '+header.name,detail:arr(model.csv.inspection.sample_rows)[0]?.[header.index]||''}))],selected=>{if(Number(selected.id)<0)delete model.csv.columns[name];else model.csv.columns[name]=Number(selected.id);renderDocument();});}
  function renderVoid(){const d=model.data,original=model.original;title('إبطال اعتماد التسوية البنكية',original.code+' • '+original.from_date+' — '+original.to_date);display(note('يبقى الكشف وشهادته الأصلية محفوظين. يلغى أثر الاعتماد على قفل حركات البنك من تاريخ تسجيل الإبطال، دون إنشاء قيد مالي. يجب إبطال أحدث تسوية للحساب أولًا.','warning')+`<section class="br-section"><div class="br-grid">${field('business_date','تاريخ الإبطال',d.business_date,'date',true)}${field('reference','مرجع المراجعة',d.reference,'text',true)}${memo('reason','سبب إبطال الاعتماد *',d.reason)}</div></section>`,button('إثبات إبطال الاعتماد','confirm-void','',true)+button('رجوع للكشف','back-document')+'<span class="br-spacer"></span>'+button('إغلاق','close'));}
  function voidForm(){if(dirty)throw Error('احفظ المسودة أو أعد فتح المستند قبل الإبطال');const original=model.data;model={view:'void',config:model.config,original,data:{request_key:crypto.randomUUID(),business_date:today(),reference:'',reason:''}};dirty=false;renderVoid();}
  async function confirmVoid(){const d=model.data,o=model.original;if(!d.business_date||!d.reference.trim()||!d.reason.trim())throw Error('أكمل تاريخ ومرجع وسبب الإبطال');const result=await api('bank-reconciliations/'+o.id+'/void','POST',{...d,revision:o.revision,event_revision:o.adjustment_revision||0});model=documentModel(model.config,result);dirty=false;renderDocument();await refresh();toast('تم إثبات إبطال الاعتماد مع حفظ الأصل');}
  const printHead=(title,context)=>`<h1>نيو بانوراما رمسيس</h1><p dir="ltr">A&amp;M — Accounting Hotel for Audit &amp;Control</p><h2>${esc(title)}</h2><p>${esc(context)}</p>`;
  const signatures=()=>'<div class="br-signatures"><span>أعدّه: ................</span><span>راجعه: ................</span><span>اعتمده: ................</span><span>التوقيع: ................</span></div>';
  function printDocument(){if(dirty||!model.data.id)throw Error('احفظ المستند قبل الطباعة');const d=model.data,p=d.status==='draft'?model.preview||d.preview:d.snapshot||model.preview;if(!p)throw Error('حدّث المعاينة قبل الطباعة');const t=p.totals||{};$('#print-document').innerHTML=printHead('شهادة التسوية البنكية',d.code+' • '+label(effective(d)))+readDetails([['البنك',frozenAccountName()],['فترة كشف البنك',d.from_date+' — '+d.to_date],['مرجع كشف البنك',d.reference],['أعدّه',d.prepared_by],['راجعه',d.reviewed_by],['رصيد كشف البنك',money(t.statement_closing_cents||0)],['الحركات الدفترية القائمة',money(t.unmatched_book_cents||0)],['الرصيد المعدل لكشف البنك',money(t.adjusted_statement_cents||0)],['الرصيد الدفتري',money(t.book_closing_cents||0)],['فرق المطابقة',money(t.difference_cents||0)],['ملاحظات',d.notes]])+note('المستند لا ينشئ قيدًا ماليًا؛ البنود القائمة تبقى مفصلة حتى ظهورها أو تصحيح مصدرها. بنود الكشف غير المطابقة: '+arr(p.unmatched_statement_lines).length)+`<h3>بنود كشف البنك</h3>`+statementReadTable(arr(p.lines||d.lines).map((line,index)=>({...line,id:line.id||index+1,amount_cents:line.amount_cents??Math.abs(cents(line.amount))*(line.direction==='withdrawal'?-1:1)})))+'<h3>مجموعات المطابقة</h3>'+groupsTable(arr(p.matches||p.groups))+'<h3>الحركات الدفترية التي لم تظهر في الكشف</h3>'+bookTable(arr(p.unmatched_book_lines))+'<h3>بنود كشف البنك غير المطابقة</h3>'+statementReadTable(arr(p.unmatched_statement_lines))+pendingCheques(p.pending_cheques,true)+(d.void?note('إبطال الاعتماد '+d.void.code+' • '+d.void.business_date+' • '+d.void.reference+' • '+d.void.reason,'warning'):'')+(d.status==='draft'?note('مسودة غير معتمدة؛ لا تثبت إتمام المطابقة.','warning'):'')+signatures();window.print();}
  function journalTable(journal){return`<div class="br-table-wrap"><table class="br-table"><thead><tr><th>الحساب</th><th>مدين</th><th>دائن</th></tr></thead><tbody>${arr(journal.lines).map(line=>`<tr><td>${esc(line.account_code)} • ${esc(line.account_name)}</td><td>${amount(line.debit_cents)}</td><td>${amount(line.credit_cents)}</td></tr>`).join('')}</tbody></table></div>`;}
  async function journal(id){const back=model,wasDirty=dirty,current=++sequence,j=await api('journals/'+Number(id));if(current!==sequence||!dialog.open)return;model={view:'journal',journal:j,back,backDirty:wasDirty};dirty=wasDirty;renderJournal();}
  function renderJournal(){title('القيد الأصلي لحركة البنك',model.journal.code+' • '+model.journal.entry_date);display(journalTable(model.journal),button('طباعة القيد','print-journal')+button('رجوع للتسوية','back')+'<span class="br-spacer"></span>'+button('إغلاق','close'));}
  function recordBankLine(id){const line=model.data.lines[id-1];if(!line)return;const back=model;model={view:'bank-line',back,line,lineId:id};renderBankLineChoice();}
  function renderBankLineChoice(){const line=model.line,back=model.back,p=back.preview||back.lastPreview||{},pending=arr(p.pending_cheques);title('مراجعة مصدر حركة كشف البنك',line.reference||line.description||'بند '+model.lineId);display(note('اختر مصدر الحركة من مستند البنك الفعلي. السحب ليس بالضرورة عمولة؛ قد يكون سداد مورد أو صرف شيك مسجلًا في دورة أخرى. لا تنشئ سندًا بنكيًا مكررًا.','warning')+`<section class="br-section">${readDetails([['تاريخ الحركة',line.date],['تاريخ القيمة',line.value_date||line.date],['مرجع البنك',line.reference],['البيان',line.description],['المبلغ',money(Math.abs(cents(line.amount)))]])}<div class="br-tools">${line.direction==='withdrawal'?button('عمولة أو مصروف بنك مباشر','record-bank-kind','data-kind="fee"')+button('مدفوع بنكي مباشر بمستند','record-bank-kind','data-kind="payment"'):button('متحصل بنكي مباشر بمستند','record-bank-kind','data-kind="receipt"')}</div>${note('فواتير الموردين وسدادها وتوريد الخصم تسجل من دوراتها الأصلية. ارجع بعد تسجيل المصدر وحدّث معاينة التسوية لتظهر الحركة للمطابقة.')}</section>${pending.length?`<section class="br-section"><h3>شيكات صادرة قائمة قد يكون صرفها ظاهرًا بالكشف</h3>${pending.map((cheque,index)=>`<div class="br-source-choice"><span><b>${esc(cheque.cheque_number||cheque.number||cheque.code||'')}</b> • ${esc(cheque.beneficiary||cheque.party_name||'')} • ${amount(cheque.amount_cents)}<small>الاستحقاق ${esc(cheque.due_date||'')}</small></span>${button('فتح مستند الشيك الأصلي','record-cheque-source',`data-index="${index}"`)}</div>`).join('')}</section>`:''}`,button('رجوع للتسوية','back-bank-line')+'<span class="br-spacer"></span>'+button('إغلاق','close'));}
  async function recordBankKind(kind){if(!['fee','payment','receipt'].includes(kind))return;const current=model,line=current.line,d=current.back.data;if(!discard())return;const preset={account_id:Number(d.account_id),amount:textAmount(Math.abs(cents(line.amount))),business_date:line.date,value_date:line.value_date||line.date,reference:line.reference||d.reference,bank_reference:line.reference||'',party_name:line.description||'',notes:'مراجعة بند كشف البنك '+d.reference};++sequence;dirty=false;dialog.close();model=null;return Banking.newDocument(kind,preset);}
  async function recordChequeSource(index){const back=model.back,p=back.preview||back.lastPreview||{},cheque=arr(p.pending_cheques)[index];if(!cheque||!discard())return;const action=cheque.action||{type:cheque.kind==='opening_cheque'?'opening_bank_cheque':'payment',id:cheque.id};++sequence;dirty=false;dialog.close();model=null;if(action.type==='opening_bank_cheque')return Banking.openCheque(Number(action.id));return SupplierAP.openPayment(Number(action.id));}
  async function source(id){const p=model.preview||model.lastPreview||model.data.snapshot,entry=bookLines(p).find(line=>bookId(line)===Number(id));if(!entry)return;const action=entry.action;if(!action)return journal(entry.journal_id);const accountId=model.data.account_id;if(!discard())return;++sequence;dirty=false;dialog.close();model=null;const ident=Number(action.id||entry.source_id);if(action.type==='bank_document')return Banking.openDocument(ident);if(action.type==='opening_bank_cheque')return Banking.openCheque(ident);if(action.type==='opening_balance')return OpeningBalances.openBatch(ident);if(['payment','supplier_payment'].includes(action.type))return SupplierAP.openPayment(ident);if(['refund','supplier_refund'].includes(action.type))return SupplierSettlement.openRefund(ident);if(['remittance','withholding_remittance'].includes(action.type))return WithholdingRemittances.open(ident);return LedgerReports.ledger(entry.account_id||accountId,{from_date:entry.entry_date,to_date:entry.entry_date});}
  async function dispatch(control){const action=control.dataset.reconciliationAction;if(action==='close')return close();if(busy)return;if(action==='list')return open();if(action==='new')return newDocument();if(action==='open')return openDocument(Number(control.dataset.id));if(action==='pick-account')return pickAccount();if(action==='add-line')return addLine();if(action==='remove-line')return removeLine(Number(control.dataset.index));if(action==='line-direction'){const index=Number(control.dataset.index);model.data.lines[index].direction=control.dataset.direction;clearLineMatches(index+1);changed();return renderDocument();}if(action==='preview')return mutate(preview);if(action==='save')return mutate(save);if(action==='confirm')return mutate(confirmDocument);if(action==='cancel')return mutate(cancelDocument);if(action==='print')return printDocument();if(action==='toggle-statement')return toggleSelection('statement',Number(control.dataset.id));if(action==='toggle-book')return toggleSelection('book',Number(control.dataset.id));if(action==='toggle-prior')return mutate(()=>togglePrior(Number(control.dataset.id)));if(action==='clear-selection'){model.selectedStatements.clear();model.selectedBooks.clear();renderDocument();return selection();}if(action==='match-selected')return mutate(matchSelected);if(action==='remove-match')return mutate(()=>removeMatch(Number(control.dataset.index)));if(action==='clear-matches'){if(confirm('إلغاء جميع مجموعات المطابقة في المسودة؟')){model.data.matches=[];changed();return mutate(preview);}return;}if(action==='suggestion')return suggest(Number(control.dataset.index));if(action==='load-csv')return csvStart();if(action==='choose-csv-file')return q('#reconciliation-csv-file').click();if(action==='inspect-csv')return mutate(inspectCsv);if(action==='parse-csv')return mutate(parseCsv);if(action==='close-csv'){model.csv=null;return renderDocument();}if(action==='pick-csv-column')return pickCsvColumn(control.dataset.column);if(action==='csv-option'){const csv=model.csv;csv[control.dataset.name]=control.dataset.value;if(control.dataset.name==='amount_mode')csv.amountModeExplicit=true;if(control.dataset.name==='encoding')decodeCsv();if(['encoding','delimiter'].includes(control.dataset.name))csv.inspection=null;return renderDocument();}if(action==='void')return voidForm();if(action==='confirm-void')return mutate(confirmVoid);if(action==='back-bank-line'){model=model.back;return renderDocument();}if(action==='record-bank-kind')return recordBankKind(control.dataset.kind);if(action==='record-cheque-source')return recordChequeSource(Number(control.dataset.index));if(action==='back-document')return openDocument(model.original.id);if(action==='journal')return journal(Number(control.dataset.id));if(action==='source')return source(Number(control.dataset.lineId));if(action==='record-bank-line')return recordBankLine(Number(control.dataset.id));if(action==='back'){const previous=model;model=previous.back;dirty=previous.backDirty;return renderDocument();}if(action==='print-journal'){$('#print-document').innerHTML=printHead('القيد الأصلي لحركة البنك',model.journal.code)+journalTable(model.journal)+signatures();return window.print();}}
  document.addEventListener('click',event=>{const entry=event.target.closest('[data-bank-reconciliation]');if(entry&&!entry.disabled){const other=entry.closest('dialog');if(other&&other!==dialog&&other.open)other.close();(entry.dataset.accountId?newDocument({account_id:Number(entry.dataset.accountId)}):open()).catch(error);}});
  return{open,newDocument,openDocument};
})();
